import{X as e,Y as t,ct as n,t as r}from"./chunks/framework.CaFWb3SA.js";var i=JSON.parse(`{"title":"运算","description":"","frontmatter":{},"headers":[],"relativePath":"translation/Operator.md","filePath":"translation/Operator.md"}`),a={name:`translation/Operator.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="运算" tabindex="-1">运算 <a class="header-anchor" href="#运算" aria-label="Permalink to “运算”">​</a></h1><blockquote><p>翻译自原文档：<a href="https://osdn.net/projects/emuera/wiki/exop" target="_blank" rel="noreferrer">https://osdn.net/projects/emuera/wiki/exop</a></p></blockquote><h2 id="运算符" tabindex="-1">运算符 <a class="header-anchor" href="#运算符" aria-label="Permalink to “运算符”">​</a></h2><h3 id="单目运算符" tabindex="-1">单目运算符 <a class="header-anchor" href="#单目运算符" aria-label="Permalink to “单目运算符”">​</a></h3><ul><li><code>~</code>：按位取反（按位 NOT），单目运算符（优先级最高）</li><li><code>!</code>：逻辑非（NOT），单目运算符（优先级最高）</li></ul><h3 id="双目运算符" tabindex="-1">双目运算符 <a class="header-anchor" href="#双目运算符" aria-label="Permalink to “双目运算符”">​</a></h3><ul><li><code>&lt;&lt;</code>：左移。优先级高于比较和位运算，低于四则运算。</li><li><code>&gt;&gt;</code>：右移。优先级高于比较和位运算，低于四则运算。</li><li><code>^</code>：按位异或（按位 XOR）。优先级与 <code>&amp;</code>、<code>|</code> 相同。</li><li><code>^^</code>：逻辑异或（XOR）。优先级与 <code>&amp;&amp;</code>、<code>||</code> 相同。</li><li><code>!&amp;</code>：逻辑与非（NAND）。优先级与 <code>&amp;&amp;</code>、<code>||</code> 相同。</li><li><code>!|</code>：逻辑或非（NOR）。优先级与 <code>&amp;&amp;</code>、<code>||</code> 相同。</li></ul><h3 id="三元运算符" tabindex="-1">三元运算符 <a class="header-anchor" href="#三元运算符" aria-label="Permalink to “三元运算符”">​</a></h3><p><code>?～#</code>：普通的三元运算符。优先级位于 <code>=</code> 之下、其余运算符之上（会先汇总判断与结果，再进行运算）。</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#9CDCFE;">书写格式（数值）：</span><span style="color:#D4D4D4;">&lt;</span><span style="color:#9CDCFE;">赋值目标变量</span><span style="color:#D4D4D4;">&gt;</span><span style="color:#D4D4D4;"> =</span><span style="color:#D4D4D4;"> &lt;</span><span style="color:#9CDCFE;">条件式</span><span style="color:#D4D4D4;">&gt;</span><span style="color:#D4D4D4;"> ?</span><span style="color:#D4D4D4;"> &lt;</span><span style="color:#9CDCFE;">为真时的值</span><span style="color:#D4D4D4;">&gt;</span><span style="color:#D4D4D4;"> #</span><span style="color:#D4D4D4;"> &lt;</span><span style="color:#9CDCFE;">为假时的值</span><span style="color:#D4D4D4;">&gt;</span></span>
<span class="line"><span style="color:#9CDCFE;">书写格式（字符串）：</span><span style="color:#D4D4D4;">&lt;</span><span style="color:#9CDCFE;">赋值目标变量</span><span style="color:#D4D4D4;">&gt;</span><span style="color:#D4D4D4;"> =</span><span style="color:#569CD6;"> \\@</span><span style="color:#D4D4D4;">&lt;</span><span style="color:#9CDCFE;">条件式</span><span style="color:#D4D4D4;">&gt; ? &lt;为真时的值&gt; # &lt;为假时的值&gt;</span><span style="color:#569CD6;">\\@</span></span></code></pre></div><p>在处理的含义上等同于：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#C586C0;">IF</span><span style="color:#D4D4D4;"> &lt;</span><span style="color:#9CDCFE;">条件式</span><span style="color:#D4D4D4;">&gt;</span></span>
<span class="line"><span style="color:#D4D4D4;">  &lt;</span><span style="color:#9CDCFE;">赋值目标变量</span><span style="color:#D4D4D4;">&gt;</span><span style="color:#D4D4D4;"> =</span><span style="color:#D4D4D4;"> &lt;</span><span style="color:#9CDCFE;">为真时的值</span><span style="color:#D4D4D4;">&gt;</span></span>
<span class="line"><span style="color:#C586C0;">ELSE</span></span>
<span class="line"><span style="color:#D4D4D4;">  &lt;</span><span style="color:#9CDCFE;">赋值目标变量</span><span style="color:#D4D4D4;">&gt;</span><span style="color:#D4D4D4;"> =</span><span style="color:#D4D4D4;"> &lt;</span><span style="color:#9CDCFE;">为假时的值</span><span style="color:#D4D4D4;">&gt;</span></span>
<span class="line"><span style="color:#C586C0;">ENDIF</span></span></code></pre></div><p>另外，数值的三元运算符放进 <code>()</code> 中就可以在普通计算中使用；字符串的三元运算符可以直接用于 <code>PRINTFORM</code> 系指令。但是，<code>\\@～\\@</code> 形式的三元运算符不能省略 <code>#</code>。</p><h3 id="赋值运算符" tabindex="-1">赋值运算符 <a class="header-anchor" href="#赋值运算符" aria-label="Permalink to “赋值运算符”">​</a></h3><ul><li><code>&#39;=</code>：使用字符串表达式向字符串型变量赋值的运算符，详见<a href="./General.html">此处</a>。</li></ul><h3 id="递增与递减" tabindex="-1">递增与递减 <a class="header-anchor" href="#递增与递减" aria-label="Permalink to “递增与递减”">​</a></h3><ul><li><code>++</code>：自增</li><li><code>--</code>：自减</li></ul><p>用于代替赋值语句，不能与其他运算符组合使用。</p><h2 id="暂定的运算符优先级表" tabindex="-1">暂定的运算符优先级表 <a class="header-anchor" href="#暂定的运算符优先级表" aria-label="Permalink to “暂定的运算符优先级表”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">分类</th><th style="text-align:center;">优先级</th><th style="text-align:center;">赋值复合运算</th><th style="text-align:center;">符号</th></tr></thead><tbody><tr><td style="text-align:center;">否定运算符</td><td style="text-align:center;">高</td><td style="text-align:center;">×</td><td style="text-align:center;"><code>~</code>, <code>!</code></td></tr><tr><td style="text-align:center;">算术运算符</td><td style="text-align:center;">↑</td><td style="text-align:center;">○</td><td style="text-align:center;"><code>*</code>, <code>/</code>, <code>%</code></td></tr><tr><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;">○</td><td style="text-align:center;"><code>+</code>, <code>-</code></td></tr><tr><td style="text-align:center;">位移运算符</td><td style="text-align:center;"></td><td style="text-align:center;">○</td><td style="text-align:center;"><code>&lt;&lt;</code>, <code>&gt;&gt;</code></td></tr><tr><td style="text-align:center;">比较运算符</td><td style="text-align:center;"></td><td style="text-align:center;">×</td><td style="text-align:center;"><code>&lt;</code>, <code>&gt;</code>, <code>&lt;=</code>, <code>&gt;=</code></td></tr><tr><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;">×</td><td style="text-align:center;"><code>==</code>, <code>!=</code></td></tr><tr><td style="text-align:center;">逻辑运算符</td><td style="text-align:center;"></td><td style="text-align:center;">○</td><td style="text-align:center;"><code>&amp;</code>, \`</td></tr><tr><td style="text-align:center;"></td><td style="text-align:center;">↓</td><td style="text-align:center;">×</td><td style="text-align:center;"><code>&amp;&amp;</code>, <code>!&amp;</code>, \`</td></tr><tr><td style="text-align:center;">三元运算符</td><td style="text-align:center;">低</td><td style="text-align:center;">×</td><td style="text-align:center;"><code>～?…#＿</code></td></tr></tbody></table><h2 id="新增的运算" tabindex="-1">新增的运算 <a class="header-anchor" href="#新增的运算" aria-label="Permalink to “新增的运算”">​</a></h2><ul><li><code>==</code>：字符串与字符串的比较。不能将数值与字符串进行比较。</li><li><code>!=</code>：字符串与字符串的比较。</li><li><code>&lt;</code>：字符串与字符串的比较。比较从开头进行，在发现不同字符的位置即确定结果。</li><li><code>&gt;</code>：字符串与字符串的比较。</li><li><code>&lt;=</code>：字符串与字符串的比较。</li><li><code>&gt;=</code>：字符串与字符串的比较。</li><li><code>+</code>：字符串与字符串的连接。数值与字符串不能相加或连接。</li><li><code>*</code>：字符串与整数的乘法。字符串与字符串不能相乘。</li></ul><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#9CDCFE;">STR</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#D4D4D4;"> =</span><span style="color:#569CD6;"> %</span><span style="color:#CE9178;"> &quot;あ&quot;</span><span style="color:#D4D4D4;"> * </span><span style="color:#B5CEA8;">10</span><span style="color:#569CD6;"> %</span></span>
<span class="line"><span style="color:#569CD6;">PRINTFORML</span><span style="color:#E6E6E6;"> STR:0 = &quot;</span><span style="color:#569CD6;">%</span><span style="color:#9CDCFE;">STR</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#569CD6;">%</span><span style="color:#E6E6E6;">&quot;</span></span>
<span class="line"><span style="color:#569CD6;">WAIT</span></span></code></pre></div><p>结果：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>STR:0 = &quot;ああああああああああ&quot;</span></span></code></pre></div><h2 id="逻辑运算符的短路求值" tabindex="-1">逻辑运算符的短路求值 <a class="header-anchor" href="#逻辑运算符的短路求值" aria-label="Permalink to “逻辑运算符的短路求值”">​</a></h2><p>短路求值是指，例如在 <code>X &amp;&amp; Y</code> 这样的表达式中，当 <code>X</code> 为 0 时，无论 <code>Y</code> 的值如何，运算结果都显然是 0，因此不再对 <code>Y</code> 求值。</p><p>包括吉里吉里在内的许多语言都会对逻辑运算符进行短路求值。</p><p>利用这种求值方式可以这样书写：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#C586C0;">IF</span><span style="color:#E6E6E6;"> (</span><span style="color:#9CDCFE;">ASSI</span><span style="color:#D4D4D4;"> &gt;=</span><span style="color:#B5CEA8;"> 0</span><span style="color:#E6E6E6;">) </span><span style="color:#D4D4D4;">&amp;&amp;</span><span style="color:#E6E6E6;"> (</span><span style="color:#9CDCFE;">NO</span><span style="color:#D4D4D4;">:</span><span style="color:#9CDCFE;">ASSI</span><span style="color:#D4D4D4;"> ==</span><span style="color:#B5CEA8;"> 1</span><span style="color:#E6E6E6;">)</span></span>
<span class="line"><span style="color:#9CDCFE;">  ～～～</span></span>
<span class="line"><span style="color:#C586C0;">ELSE</span></span>
<span class="line"><span style="color:#9CDCFE;">  ～～～</span></span>
<span class="line"><span style="color:#C586C0;">ENDIF</span></span></code></pre></div><p>当 <code>ASSI</code> 为 0 或更小时，无论 <code>(NO:ASSI == 1)</code> 的结果如何，整体结果都是 0，因此不会引用 <code>NO:ASSI</code>，也就不会发生错误。</p><p>求值顺序是先左项、后右项。</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#C586C0;">IF</span><span style="color:#E6E6E6;"> (</span><span style="color:#9CDCFE;">NO</span><span style="color:#D4D4D4;">:</span><span style="color:#9CDCFE;">ASSI</span><span style="color:#D4D4D4;"> ==</span><span style="color:#B5CEA8;"> 1</span><span style="color:#E6E6E6;">) </span><span style="color:#D4D4D4;">&amp;&amp;</span><span style="color:#E6E6E6;"> (</span><span style="color:#9CDCFE;">ASSI</span><span style="color:#D4D4D4;"> &gt;=</span><span style="color:#B5CEA8;"> 0</span><span style="color:#E6E6E6;">)</span></span></code></pre></div><p>这样书写时会先计算 <code>(NO:ASSI == 1)</code>，因此当 <code>ASSI &lt; 0</code> 时就会发生错误。</p>`,34)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};